// Security headers for every response this Worker generates.
//
// This has to exist *alongside* the root `_headers` file rather than instead of it.
// Cloudflare applies `_headers` only to static assets it serves directly — not to
// responses generated by Worker code — and nothing in this app is prerendered
// (`grep -rn prerender src/routes` finds nothing), so every HTML page a visitor actually
// loads comes from the Worker and would be left bare by `_headers` alone. The two files
// carry the same four headers so an asset and a page are protected identically.
//
// Deliberately no Content-Security-Policy here yet. A useful one for this app is not
// trivial — SvelteKit inlines its hydration bootstrap (and only adds a nonce when
// `kit.csp` is configured), the ONNX runtime needs `'wasm-unsafe-eval'`, the search Web
// Worker needs `worker-src`, and the relay needs an explicit cross-origin `connect-src`
// for `wss://`. A CSP that silently breaks semantic search is worse than no CSP, so it
// belongs in its own change, developed in report-only mode and gated on the e2e suite
// passing with it enforced.

import type { Handle } from '@sveltejs/kit';

/**
 * A redirect for a path `decodeURI` refuses, or null for every other path.
 *
 * SvelteKit's server answers one with a 400 page, and its client then throws decoding the same path
 * while it starts, so that page never hydrates: no palette, no shortcuts, no `?ws=` written back.
 * Only the server can do anything about that, because the client is what fails. Doubling each `%`
 * makes the path say what was typed, which is then an ordinary issue or page that isn't found.
 *
 * Absolute, because a path can start with `//`, and as a Location that would mean another host.
 */
function redirectMalformedPath(url: URL): Response | null {
	try {
		decodeURI(url.pathname);
		return null;
	} catch {
		const encoded = new URL(url);
		encoded.pathname = url.pathname.replaceAll('%', '%25');
		return new Response(null, { status: 308, headers: { location: encoded.href } });
	}
}

export const handle: Handle = async ({ event, resolve }) => {
	const response = redirectMalformedPath(event.url) ?? (await resolve(event));

	// Stops a browser from second-guessing a declared Content-Type — the mitigation for
	// "upload something that sniffs as script".
	response.headers.set('X-Content-Type-Options', 'nosniff');
	// A workspace id is the only thing protecting a workspace (ADR 0004), and it lives in
	// the URL — so the Referer sent to any third party must never carry the path.
	response.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
	// Clickjacking. Relax to SAMEORIGIN (or drop in favour of a `frame-ancestors` CSP
	// listing the embedding origin) if this demo is ever meant to be iframed elsewhere.
	response.headers.set('X-Frame-Options', 'DENY');
	response.headers.set(
		'Permissions-Policy',
		'camera=(), microphone=(), geolocation=(), payment=(), usb=()'
	);

	return response;
};
